<?php

declare(strict_types=1);

namespace Tests\Pwa;

use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

/**
 * PWA icons are code-generated by scripts/generate-pwa-icons.php (ext-gd)
 * and committed together with the script: exact sizes, valid loadable PNGs,
 * color constants present in the generator.
 */
final class PwaIconTest extends TestCase
{
    private string $base;

    protected function setUp(): void
    {
        $this->base = dirname(__DIR__);
    }

    public function testGeneratorScriptExistsWithColorConstants(): void
    {
        $script = $this->base . '/scripts/generate-pwa-icons.php';
        $this->assertFileExists($script);
        $src = (string)file_get_contents($script);
        $this->assertStringContainsString('14532d', $src, 'gradient top #14532d');
        $this->assertStringContainsString('16a34a', $src, 'gradient bottom #16a34a');
        $this->assertStringContainsString('ffffff', $src, 'motif white #ffffff');
        $this->assertStringContainsString('icon-192.png', $src);
        $this->assertStringContainsString('icon-512.png', $src);
        $this->assertStringContainsString('icon-512-maskable.png', $src);
    }

    /** @return array<string, array{0: string, 1: int}> */
    public static function iconProvider(): array
    {
        return [
            '192' => ['icon-192.png', 192],
            '512' => ['icon-512.png', 512],
            '512 maskable' => ['icon-512-maskable.png', 512],
        ];
    }

    private function iconPath(string $file): string
    {
        return $this->base . '/public/assets/icons/' . $file;
    }

    #[DataProvider('iconProvider')]
    public function testIconExistsWithExactDimensions(string $file, int $size): void
    {
        $path = $this->base . '/public/assets/icons/' . $file;
        $this->assertFileExists($path, $file);
        $this->assertGreaterThan(0, (int)filesize($path), $file . ' must be non-empty');
        $info = getimagesize($path);
        $this->assertNotFalse($info, $file . ' must be a readable image');
        $this->assertSame('image/png', $info['mime'], $file);
        $this->assertSame($size, $info[0], $file . ' width');
        $this->assertSame($size, $info[1], $file . ' height');
    }

    #[DataProvider('iconProvider')]
    public function testIconIsLoadablePng(string $file, int $size): void
    {
        $this->assertTrue(extension_loaded('gd'), 'gd extension must be enabled (CI installs it)');
        $path = $this->base . '/public/assets/icons/' . $file;
        $img = @imagecreatefrompng($path);
        $this->assertInstanceOf(\GdImage::class, $img, $file . ' must load via imagecreatefrompng');
        $this->assertSame($size, imagesx($img), $file . ' width');
        $this->assertSame($size, imagesy($img), $file . ' height');
        imagedestroy($img);
    }

    #[DataProvider('iconProvider')]
    public function testIconHasExpectedBrandColors(string $file, int $size): void
    {
        $this->assertTrue(extension_loaded('gd'));
        $img = imagecreatefrompng($this->iconPath($file));
        // Sample 2% in from the top/bottom edge on the center column: the
        // outermost 1-2 rows can blend with the transparent canvas edge
        // depending on the rasterizer's resampling (GD vs reference), so the
        // assertion targets the gradient body, not the border pixels.
        $yTop = max(1, (int)round($size * 0.02));
        $yBottom = min($size - 2, (int)round($size * 0.98));
        $top = imagecolorat($img, (int)($size / 2), $yTop);
        $this->assertEqualsWithDelta(0x14, ($top >> 16) & 0xFF, 3, 'top red channel');
        $this->assertEqualsWithDelta(0x53, ($top >> 8) & 0xFF, 3, 'top green channel');
        $this->assertEqualsWithDelta(0x2D, $top & 0xFF, 3, 'top blue channel');
        $bottom = imagecolorat($img, (int)($size / 2), $yBottom);
        $this->assertEqualsWithDelta(0x16, ($bottom >> 16) & 0xFF, 3, 'bottom red channel');
        $this->assertEqualsWithDelta(0xA3, ($bottom >> 8) & 0xFF, 3, 'bottom green channel');
        $this->assertEqualsWithDelta(0x4A, $bottom & 0xFF, 3, 'bottom blue channel');
        // the white motif (book + bar) must appear on the center column:
        // scan the middle band; the solid bar guarantees a white pixel at x=center
        $foundWhite = false;
        for ($y = (int)round($size * 0.40); $y < (int)round($size * 0.75); $y++) {
            $c = imagecolorat($img, (int)($size / 2), $y);
            if ((($c >> 16) & 0xFF) > 0xE0 && (($c >> 8) & 0xFF) > 0xE0 && ($c & 0xFF) > 0xE0) {
                $foundWhite = true;
                break;
            }
        }
        $this->assertTrue($foundWhite, $file . ': white motif pixel expected in the center band');
        imagedestroy($img);
    }
}
